import { GameConnection, IBaseParentEvents, IChatParentEvents, IGameChildEvents, IKeyboardStatePayload, IOperatorParentEvents, IProvideChatColoursPayload, IChatLinksPayload } from '@game-studio/shell-connection';
import { OverlaysEventEmitter } from '@game-studio/overlays';
import { IPlayerData } from '@game-studio/server-comms/dist/types/request-response/models/player-data';

import { userModel } from '../models/user';
import { eventEmitter } from '../services/event-emitter';
import { queryStringParams } from '../services/query-string';
import { device } from '../services/device';
import { BaseGame, container, environment, sessionDataModel } from '..';
import { mappedChatColours } from '../views/settings-menu/chat-colours';
import { inversifyContainer } from '../inversify/container';
import { demoState } from '../models/demo-model';
import { useCompanionState } from '../models/companion-state';

export interface IArcadeWinnerPayload {
    username: string;
    prize: number;
    game: string;
    skin: string;
}

export class GameConnectionFactory {
    public static create(): GameConnection {
        function operatorHandlers(gameName: string): IGameChildEvents {
            return {
                authenticate(payload: { userId: number | string; crossCheck: number; }) {
                    //Sisal can send through strings as well as numbers for the user id so need to make sure we convert it for our use
                    const payloadId = typeof payload.userId === 'number' ? payload.userId :
                        (payload.userId[0] !== '0' && !isNaN(Number(payload.userId))) ? parseInt(payload.userId, 10) : payload.userId;

                    userModel.setCredentials(payloadId, payload.crossCheck);
                    container.frameConnection.operator.onAuthenticated({ balance: userModel.totalBalance.endBalance, gameId: gameName });
                },
                getSessionInfo() {
                    // TODO: unclear if this is used currently
                    return {
                        userId: userModel.userId,
                        crossCheck: userModel.crossCheck,
                        username: userModel.username,
                        sessionResumptionAuthId: '', // TODO: this probably needs to be correct if this data gets used
                        totalBalance: Math.floor(userModel.totalBalance.endBalance / 100),
                        totalBalanceAsPence: userModel.totalBalance.endBalance
                    };
                },
                onSessionInfo(payload): void {
                    const playerData: IPlayerData = {
                        EndBalance: payload.balance,
                        FreePlayBalance: userModel.freePlayBalance,
                        PreStakeBalance: userModel.totalBalance.startBalance,
                        PreviousStake: userModel.previousStake,
                        StartBalance: userModel.totalBalance.startBalance,
                        Username: userModel.username
                    };
                    userModel.setData(playerData, 'FromBingo');
                    sessionDataModel.setData('FromBingo', payload.managerStatus, payload.managerSettings);
                    if (!demoState.isDemoMode && !container.cabinet.inFreePlay) {
                        container.cabinet.setCurrentBalance(inversifyContainer.currencyFormatter.precise(userModel.visibleBalance.endBalance));
                    }
                },
                openSubGame() {
                    // No Implementation
                },
                openSubGameUrl() {
                    // No Implementation
                },
                disconnect() { },
                setKeyboardState(payload: IKeyboardStatePayload) {
                    device.keyboard.height = payload.height;
                    device.keyboard.isOpen = payload.isOpen;

                    if (!payload.isOpen) {
                        inversifyContainer.frameConnection.chat.onLoseFocus();
                    }
                }
            };
        }

        function chatHandlers(): Omit<IChatParentEvents, keyof IBaseParentEvents> {
            return {
                onInit() { },
                onKeyboardOpened(payload: { isOpen: boolean }) {
                    if (!device.type.isApp) {
                        device.keyboard.isOpen = payload.isOpen;
                    }
                },
                goToLobby() { },
                onArcadeWinner(response: IArcadeWinnerPayload) {
                    const localisedGameName = queryStringParams.locale === 'en-gb' ? response.game : BaseGame.gameNameMap[response.game.toLowerCase()];

                    OverlaysEventEmitter.emit('showTopPrize', {
                        game: localisedGameName,
                        isPromo: false,
                        username: response.username,
                        message: '',
                        prize: response.prize,
                        promoValue: {
                            notificationMessage: '',
                            backgroundColour: 0,
                            apiURL: '',
                            expandedNotificationMessage: '',
                            expandedNotificationAdditionalMessage: '',
                            apiKey: ''
                        }
                    });
                },
                onLiveChatClicked() {
                    container.frameConnection.operator.onUserActionRequired({
                        type: 'navigation',
                        data: {
                            type: 'url',
                            location: container.endPoints.urls[environment].chatHelp
                        }
                    });
                },
                onLinkClicked(payload: IChatLinksPayload) {
                    container.frameConnection.operator.onUserActionRequired({
                        type: 'navigation',
                        data: {
                            type: 'url',
                            location: payload.url
                        }
                    });
                },
                onMessageReceived() { },
                setChatColour() { },
                toggleFullScreen() {
                    eventEmitter.emit('CHAT_TOGGLE_FULL_SCREEN');
                },
                onChatNotification() {
                    const companionState = useCompanionState();
                    if (!companionState.isChatOpen.value) {
                        companionState.isChatNotificationVisible.value = true;
                    }
                },
                provideAllChatColours(response: IProvideChatColoursPayload[]) {
                    const chatColours = mappedChatColours(response);
                    const companionState = useCompanionState();
                    companionState.setChatColours(chatColours);
                    eventEmitter.emit('CHAT_COLOURS_PROVIDED', companionState.chatColours.value);
                }
            };
        }

        // Arcade games don't currently have a SubGame so none of these are used
        function subGameProxyHandlers(): Omit<IOperatorParentEvents, 'onInit' | 'onLoaded' | 'onAuthenticated' | 'onSessionTimeout' | 'onStyleUpdate'> {
            return {
                updateGameInPlay() { },
                onUserActionRequired() { },
                onSessionInfo() { },
                onError() { },
                onGameRedirect() { },
                onRequestSubGameUrl() { },
                onCloseGame() { },
                openSubGame() { },
                openSubGameUrl() { },
                onOperatorMessage() { },
                onGameStart() { },
                onGameEnd() { }
            };
        }

        if (device.type.isNative) {
            return new GameConnection({
                type: 'native',
                platform: device.type.isIosNative ? 'ios' : 'android',
                chatHandlers: chatHandlers(),
                operatorHandlers: operatorHandlers(queryStringParams.currentSkin),
                subGameProxyHandlers: subGameProxyHandlers()
            });
        } else {
            return new GameConnection({
                type: 'web',
                chatHandlers: chatHandlers(),
                operatorHandlers: operatorHandlers(queryStringParams.currentSkin),
                subGameProxyHandlers: subGameProxyHandlers()
            });
        }
    }
}